#[derive(Debug)]
pub struct Config {
    pub server_port: u16,
    pub retries: u8,
}

#[derive(Debug)]
pub enum ConfigError {
    Invalid { field: &'static str, reason: String },
}

pub fn validate(config: &Config) -> Result<(), ConfigError> {
    if config.server_port == 0 {
        return Err(ConfigError::Invalid {
            field: "server_port",
            reason: String::from("0 is reserved"),
        });
    }
    if config.retries > 10 {
        return Err(ConfigError::Invalid {
            field: "retries",
            reason: format!("{} exceeds maximum of 10", config.retries),
        });
    }
    Ok(())
}
